INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT001', 'HDSAT-RW-M17-CT001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Medium', 'multiple_choice', 'Text 1
Nuclear power is the use of nuclear reactions to produce electricity. Nuclear power can be obtained from nuclear fission, nuclear decay and nuclear fusion reactions. Presently, the vast majority of electricity from nuclear power is produced by nuclear fission of uranium and plutonium in nuclear power plants. Nuclear decay processes are used in niche applications such as radioisotope thermoelectric generators in some space probes such as Voyager 2. Reactors producing controlled fusion power have been operated since 1958 but have yet to generate net power and are not expected to be commercially available in the near future.
The first nuclear power plant was built in the 1950s. The global installed nuclear capacity grew to 100 GW in the late 1970s, and then expanded during the 1980s, reaching 300 GW by 1990. The 1979 Three Mile Island accident in the United States and the 1986 Chernobyl disaster in the Soviet Union resulted in increased regulation and public opposition to nuclear power plants.

Text 2
On 26 April 1986, reactor 4 of the Chernobyl Nuclear Power Plant, located near Pripyat in the Ukrainian SSR of the Soviet Union, exploded. The accident resulted in dozens of direct deaths and a major release of radioactive material into the environment, causing widespread health effects and requiring the establishment of the Chernobyl exclusion zone. The response involved more than 500,000 personnel and cost an estimated 18 billion rubles (about $85 billion in 2026). It remains the most destructive nuclear disaster and the most expensive disaster in history, with an estimated cost of US$700 billion. It is one of only two nuclear accidents rated at the maximum severity on the International Nuclear Event Scale, the other being the 2011 Fukushima nuclear accident in Japan.
The disaster occurred while conducting a test to simulate the cooling of the reactor during a serious accident in blackout conditions. The operators carried out the test following an accidental drop in reactor power. Upon shutting down the reactor in an unstable condition, underlying design flaws led to a huge uncontrollable power surge.', 'Which choice best describes the relationship between the two texts?', '[{"id": "A", "text": "Text 2 argues that nuclear power should replace fossil fuels, while Text 1 describes the risks of doing so."}, {"id": "B", "text": "Text 1 claims that accidents like Chernobyl were impossible to prevent, while Text 2 explains the safety measures that prevented them."}, {"id": "C", "text": "Text 1 traces the growth of nuclear power and notes that accidents affected its public standing, while Text 2 describes the human and financial scale of one such accident."}, {"id": "D", "text": "Both texts focus on the technical process by which nuclear reactors generate electricity."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Nuclear power" and "Chernobyl disaster", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Nuclear_power ; https://en.wikipedia.org/wiki/Chernobyl_disaster', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT001', 'C', ARRAY['C']::TEXT[], 'Text 1 is a broad account of nuclear power''s expansion that closes by linking two accidents to regulation and public opposition. Text 2 narrows to Chernobyl and measures its casualties, response effort and cost, illustrating the kind of event Text 1 gestures toward.', '{"A": "Text 2 never advocates replacing fossil fuels; it recounts the costs of the Chernobyl accident.", "D": "Text 1 mentions fission only in passing, and neither text explains how a reactor operates.", "B": "Text 1 does not claim such accidents were impossible to prevent, and Text 2 says design flaws led to an uncontrollable power surge rather than describing measures that prevented one."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT002', 'HDSAT-RW-M17-CT002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Hard', 'multiple_choice', 'Text 1
Nuclear power is the use of nuclear reactions to produce electricity. Nuclear power can be obtained from nuclear fission, nuclear decay and nuclear fusion reactions. Presently, the vast majority of electricity from nuclear power is produced by nuclear fission of uranium and plutonium in nuclear power plants. Nuclear decay processes are used in niche applications such as radioisotope thermoelectric generators in some space probes such as Voyager 2. Reactors producing controlled fusion power have been operated since 1958 but have yet to generate net power and are not expected to be commercially available in the near future.
The first nuclear power plant was built in the 1950s. The global installed nuclear capacity grew to 100 GW in the late 1970s, and then expanded during the 1980s, reaching 300 GW by 1990. The 1979 Three Mile Island accident in the United States and the 1986 Chernobyl disaster in the Soviet Union resulted in increased regulation and public opposition to nuclear power plants.

Text 2
On 26 April 1986, reactor 4 of the Chernobyl Nuclear Power Plant, located near Pripyat in the Ukrainian SSR of the Soviet Union, exploded. The accident resulted in dozens of direct deaths and a major release of radioactive material into the environment, causing widespread health effects and requiring the establishment of the Chernobyl exclusion zone. The response involved more than 500,000 personnel and cost an estimated 18 billion rubles (about $85 billion in 2026). It remains the most destructive nuclear disaster and the most expensive disaster in history, with an estimated cost of US$700 billion. It is one of only two nuclear accidents rated at the maximum severity on the International Nuclear Event Scale, the other being the 2011 Fukushima nuclear accident in Japan.
The disaster occurred while conducting a test to simulate the cooling of the reactor during a serious accident in blackout conditions. The operators carried out the test following an accidental drop in reactor power. Upon shutting down the reactor in an unstable condition, underlying design flaws led to a huge uncontrollable power surge.', 'Based on the texts, how would the author of Text 2 most likely respond to the claim in Text 1 that accidents at nuclear plants have influenced how the public regards nuclear power?', '[{"id": "A", "text": "By arguing that increased regulation after accidents has made nuclear power unnecessary."}, {"id": "B", "text": "By disputing that the Chernobyl accident caused any direct deaths."}, {"id": "C", "text": "By claiming that public opinion about nuclear power is unrelated to plant safety."}, {"id": "D", "text": "By describing costs and casualties on a scale that would make public opposition to nuclear power understandable."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Nuclear power" and "Chernobyl disaster", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Nuclear_power ; https://en.wikipedia.org/wiki/Chernobyl_disaster', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT002', 'D', ARRAY['D']::TEXT[], 'Text 1 says Chernobyl resulted in increased regulation and public opposition. Text 2 supplies the substance behind that reaction: dozens of direct deaths, a major release of radioactive material, an exclusion zone, half a million responders and costs in the hundreds of billions.', '{"B": "Text 2 states that the accident resulted in dozens of direct deaths, so it does not deny that people died.", "A": "Text 2 does not discuss whether regulation makes nuclear power unnecessary; that judgment is not in the passage.", "C": "Text 2 details deaths, contamination and enormous expense, which connects plant safety to public concern rather than separating them."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT003', 'HDSAT-RW-M17-CT003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Medium', 'multiple_choice', 'Text 1
Remote work is the practice of working at or from one''s home or another space rather than from an office or workplace.
The practice of working at home has been documented for centuries, but remote work for large employers began on a small scale in the 1970s when technology was developed that could link satellite offices to downtown mainframes through dumb terminals using telephone lines as a network bridge. It became more common in the 1990s and 2000s, facilitated by internet technologies such as collaborative software on cloud computing and conference calling via videotelephony. In 2020, workplace hazard controls during the COVID-19 pandemic catalyzed a rapid transition to remote work for white-collar workers around the world. This shift largely persisted even after restrictions were lifted.
Proponents of a geographically distributed workforce argue that it reduces costs associated with maintaining an office, grants employees greater autonomy and flexibility—which improves their motivation and job satisfaction—eliminates environmental harms from commuting, allows employers to access a more geographically diverse pool of applicants, and enables employees to live where they prefer.
Opponents of remote work argue that remote telecommunications technology has been unable to fully replicate the advantages of face-to-face interaction, that employees may be more easily distracted, and that reduced social interaction may lead to feelings of isolation.

Text 2
Open plan is the generic term used in architectural and interior design for any floor plan that makes use of large, open spaces and minimizes the use of small, enclosed rooms such as private offices. The term can also refer to landscaping of housing estates, business parks, etc., in which there are no defined property boundaries, such as hedges, fences, or walls.
Open-plan office designs (e.g., tables with no visual barriers) reduce short-term building costs, compared to cubicles or private offices, but result in persistently lower productivity, dramatically fewer face-to-face interactions among staff, and a higher number of sick days.  An open office plan may have permanently assigned spaces at a table, or it may be used as a flex space or hot desking program.
In residential design, open plan or open concept (the term used mainly in Canada) describes the elimination of barriers such as walls and doors that traditionally separated distinct functional areas, such as combining the kitchen, living room, and dining room into a single great room.', 'Which choice best describes the relationship between the two texts?', '[{"id": "A", "text": "Both texts conclude that open-plan offices are the most efficient way to house employees."}, {"id": "B", "text": "Text 1 reports the results of a study that Text 2 then evaluates and rejects."}, {"id": "C", "text": "Text 1 presents competing assessments of working away from an office, while Text 2 describes costs associated with a particular kind of office layout."}, {"id": "D", "text": "Text 2 offers evidence that remote work improves productivity, while Text 1 questions whether employees can work from home."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Remote work" and "Open plan", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Remote_work ; https://en.wikipedia.org/wiki/Open_plan', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT003', 'C', ARRAY['C']::TEXT[], 'Text 1 lays out what proponents and opponents say about remote work. Text 2 turns to a different arrangement, open-plan offices, and reports that their short-term savings come with lower productivity, fewer face-to-face interactions and more sick days.', '{"D": "Text 2 does not discuss remote work or its productivity; it concerns open-plan offices.", "A": "Neither text endorses open-plan offices, and Text 2 reports lower productivity in them.", "B": "Text 1 cites no study, and Text 2 does not evaluate one."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT004', 'HDSAT-RW-M17-CT004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Hard', 'multiple_choice', 'Text 1
Remote work is the practice of working at or from one''s home or another space rather than from an office or workplace.
The practice of working at home has been documented for centuries, but remote work for large employers began on a small scale in the 1970s when technology was developed that could link satellite offices to downtown mainframes through dumb terminals using telephone lines as a network bridge. It became more common in the 1990s and 2000s, facilitated by internet technologies such as collaborative software on cloud computing and conference calling via videotelephony. In 2020, workplace hazard controls during the COVID-19 pandemic catalyzed a rapid transition to remote work for white-collar workers around the world. This shift largely persisted even after restrictions were lifted.
Proponents of a geographically distributed workforce argue that it reduces costs associated with maintaining an office, grants employees greater autonomy and flexibility—which improves their motivation and job satisfaction—eliminates environmental harms from commuting, allows employers to access a more geographically diverse pool of applicants, and enables employees to live where they prefer.
Opponents of remote work argue that remote telecommunications technology has been unable to fully replicate the advantages of face-to-face interaction, that employees may be more easily distracted, and that reduced social interaction may lead to feelings of isolation.

Text 2
Open plan is the generic term used in architectural and interior design for any floor plan that makes use of large, open spaces and minimizes the use of small, enclosed rooms such as private offices. The term can also refer to landscaping of housing estates, business parks, etc., in which there are no defined property boundaries, such as hedges, fences, or walls.
Open-plan office designs (e.g., tables with no visual barriers) reduce short-term building costs, compared to cubicles or private offices, but result in persistently lower productivity, dramatically fewer face-to-face interactions among staff, and a higher number of sick days.  An open office plan may have permanently assigned spaces at a table, or it may be used as a flex space or hot desking program.
In residential design, open plan or open concept (the term used mainly in Canada) describes the elimination of barriers such as walls and doors that traditionally separated distinct functional areas, such as combining the kitchen, living room, and dining room into a single great room.', 'Based on the texts, how would the author of Text 2 most likely respond to the claim in Text 1 that a distributed workforce reduces the costs of maintaining an office?', '[{"id": "A", "text": "By noting that a lower-cost office arrangement can bring offsetting losses in productivity."}, {"id": "B", "text": "By denying that employers can save money by changing how they house employees."}, {"id": "C", "text": "By insisting that face-to-face interaction has no effect on how well employees work."}, {"id": "D", "text": "By arguing that employees who work from home are more easily distracted."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Remote work" and "Open plan", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Remote_work ; https://en.wikipedia.org/wiki/Open_plan', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT004', 'A', ARRAY['A']::TEXT[], 'Text 2''s pattern is directly relevant: a cheaper layout reduces short-term building costs but results in persistently lower productivity. That supports the idea that a cost saving in office space can be offset by losses elsewhere.', '{"B": "Text 2 accepts that open-plan designs reduce short-term building costs, so it does not deny that savings are possible.", "D": "Distraction is attributed to remote work by the opponents in Text 1, not by the author of Text 2.", "C": "Text 2 reports that open-plan offices produce fewer face-to-face interactions, which implies such interaction matters rather than that it has no effect."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT005', 'HDSAT-RW-M17-CT005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Medium', 'multiple_choice', 'Text 1
A standardized test is a test that is administered and scored in a consistent or standard manner. Standardized tests are designed in such a way that the questions and interpretations are consistent and are administered and scored in a predetermined, standard manner.
A standardized test is administered and scored uniformly for all test takers. Any test in which the same test is given in the same manner to all test takers, and graded in the same manner for everyone, is a standardized test. Standardized tests do not need to be high-stakes tests, time-limited tests, multiple-choice tests, academic tests, or tests given to large numbers of test takers. Standardized tests can take various forms, including written, oral, or practical test.  The standardized test may evaluate many subjects, including driving, creativity, athleticism, personality, professional ethics, as well as academic skills.
The opposite of standardized testing is non-standardized testing, in which either significantly different tests are given to different test takers, or the same test is assigned under significantly different conditions or evaluated differently.

Text 2
Educational assessment or educational evaluation is the systematic process of documenting and using empirical data on the knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning. Assessment data can be obtained by examining student work directly to assess the achievement of learning outcomes or it is based on data from which one can make inferences about learning. Assessment is often used interchangeably with test but is not limited to tests. Assessment can focus on the individual learner, the learning community (class, workshop, or other organized group of learners), a course, an academic program, the institution, or the educational system as a whole (also known as granularity). The word "assessment" came into use in an educational context after the Second World War.
As a continuous process, assessment establishes measurable student learning outcomes, provides a sufficient amount of learning opportunities to achieve these outcomes, implements a systematic way of gathering, analyzing, and interpreting evidence to determine how well student learning matches expectations, and uses the collected information to give feedback on the improvement of students'' learning. Assessment is an important aspect of the educational process, which determines the level of accomplishments of students.
The final purpose of assessment practices in education depends on the theoretical framework of practitioners and researchers, their assumptions and beliefs about the nature of the human mind, the origin of knowledge, and the process of learning.', 'Which choice best describes the relationship between the two texts?', '[{"id": "A", "text": "Text 2 traces the history of standardized testing, while Text 1 describes how assessment data are used."}, {"id": "B", "text": "Both texts treat assessment and testing as interchangeable terms."}, {"id": "C", "text": "Text 1 defines a kind of test by how it is administered and scored, while Text 2 describes a broader process that can draw on tests without being limited to them."}, {"id": "D", "text": "Text 1 argues that standardized tests are always high-stakes, while Text 2 argues that assessment should never be graded."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Standardized test" and "Educational assessment", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Standardized_test ; https://en.wikipedia.org/wiki/Educational_assessment', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT005', 'C', ARRAY['C']::TEXT[], 'Text 1 is a definition of standardized testing as uniform administration and scoring, including forms that are not multiple-choice or academic. Text 2 defines assessment as a systematic process for gathering and using evidence to improve learning, a category wider than testing.', '{"D": "Text 1 explicitly says standardized tests do not need to be high-stakes, and Text 2 does not say assessment should never be graded.", "B": "Text 2 says assessment is often used interchangeably with test but is not limited to tests, which distinguishes the terms rather than merging them.", "A": "Text 2 mentions the word assessment entering education after the Second World War, not the history of standardized testing, and Text 1 does not describe uses of assessment data."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT006', 'HDSAT-RW-M17-CT006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Hard', 'multiple_choice', 'Text 1
A standardized test is a test that is administered and scored in a consistent or standard manner. Standardized tests are designed in such a way that the questions and interpretations are consistent and are administered and scored in a predetermined, standard manner.
A standardized test is administered and scored uniformly for all test takers. Any test in which the same test is given in the same manner to all test takers, and graded in the same manner for everyone, is a standardized test. Standardized tests do not need to be high-stakes tests, time-limited tests, multiple-choice tests, academic tests, or tests given to large numbers of test takers. Standardized tests can take various forms, including written, oral, or practical test.  The standardized test may evaluate many subjects, including driving, creativity, athleticism, personality, professional ethics, as well as academic skills.
The opposite of standardized testing is non-standardized testing, in which either significantly different tests are given to different test takers, or the same test is assigned under significantly different conditions or evaluated differently.

Text 2
Educational assessment or educational evaluation is the systematic process of documenting and using empirical data on the knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning. Assessment data can be obtained by examining student work directly to assess the achievement of learning outcomes or it is based on data from which one can make inferences about learning. Assessment is often used interchangeably with test but is not limited to tests. Assessment can focus on the individual learner, the learning community (class, workshop, or other organized group of learners), a course, an academic program, the institution, or the educational system as a whole (also known as granularity). The word "assessment" came into use in an educational context after the Second World War.
As a continuous process, assessment establishes measurable student learning outcomes, provides a sufficient amount of learning opportunities to achieve these outcomes, implements a systematic way of gathering, analyzing, and interpreting evidence to determine how well student learning matches expectations, and uses the collected information to give feedback on the improvement of students'' learning. Assessment is an important aspect of the educational process, which determines the level of accomplishments of students.
The final purpose of assessment practices in education depends on the theoretical framework of practitioners and researchers, their assumptions and beliefs about the nature of the human mind, the origin of knowledge, and the process of learning.', 'Based on the texts, how would the author of Text 2 most likely respond to the claim in Text 1 that standardized tests do not have to measure academic skills?', '[{"id": "A", "text": "By arguing that only academic skills can be measured systematically."}, {"id": "B", "text": "By agreeing, since assessment can document attitudes, aptitude and beliefs as well as knowledge."}, {"id": "C", "text": "By asserting that assessment is limited to formal tests."}, {"id": "D", "text": "By claiming that standardized tests are always administered to large numbers of test takers."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Standardized test" and "Educational assessment", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Standardized_test ; https://en.wikipedia.org/wiki/Educational_assessment', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT006', 'B', ARRAY['B']::TEXT[], 'Text 2''s definition of assessment covers attitudes, aptitude and beliefs alongside knowledge, which is consistent with Text 1''s point that standardized tests can evaluate subjects such as personality and professional ethics, not only academic skills.', '{"A": "Text 2 lists knowledge, skill, attitudes, aptitude and beliefs as targets of assessment, so it does not restrict measurement to academic skills.", "D": "Text 1 says standardized tests need not be given to large numbers of test takers, and Text 2 does not claim otherwise.", "C": "Text 2 states that assessment is not limited to tests, which contradicts the claim that it is."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT007', 'HDSAT-RW-M17-CT007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Medium', 'multiple_choice', 'Text 1
An electric vehicle (EV) is a vehicle propelled mostly by electric power. EVs encompass electric cars and other electric road vehicles (buses, trucks and personal transporters) as well as other types of land vehicles, such as electric rail vehicles (trains, trams and monorails). It also includes electric watercraft (boats and submersibles), aircraft (fixed-wing and multirotors), and spacecraft.
EVs originated in the late 19th century. Electricity was among the preferred methods for powering early motor vehicles because it was quieter, provided comfort, and ease of operation. However, its limited range hindered mass adoption throughout the 20th century. Internal combustion engines were the dominant propulsion mechanisms for cars and trucks for about 100 years, although electricity-powered locomotion became commonplace in other vehicle types, such as overhead line-powered mass transit vehicles, as well as special purpose vehicles such as mobility scooters.
Since the late 20th century, technological advances in lithium batteries—which offer superior energy density and current output versus lead-acid batteries—have revived public interest as zero-emission vehicle options.

Text 2
Ethanol fuel is an alcohol-based fuel commonly produced by fermenting sugars from crops such as corn, sugarcane, and other biomass, although it can also be synthesized from petroleum derivatives. While it is the same type of alcohol as found in alcoholic beverages, it is most often used as an alternative to gasoline in transportation, either as a pure fuel or blended into gasoline mixtures as a biofuel additive, to reduce reliance on fossil fuels and lower greenhouse gas emissions. Ethanol fuel in Brazil and the United States dominate global ethanol production, together accounting for the majority of supply, and many countries mandate ethanol blending in automotive fuels.
Historically, ethanol has been used as a fuel since the early 20th century, with Brazil pioneering large-scale adoption during the 1970s energy crisis. Advances in flexible-fuel vehicle technology and government policies have expanded its use worldwide. Ethanol''s chemical composition (C2H5OH) allows it to burn cleanly, producing carbon dioxide and water, and its high octane rating makes it suitable for high-compression engines. Most ethanol is produced through microbial fermentation of sugars, followed by distillation and dehydration, though synthetic ethanol from ethylene remains a small share of global output.
Ethanol is considered a renewable energy source, but its production raises environmental and economic concerns.', 'Which choice best describes the relationship between the two texts?', '[{"id": "A", "text": "Both texts describe alternatives to gasoline-powered vehicles, but Text 1 emphasizes battery technology while Text 2 emphasizes a crop-based fuel and its drawbacks."}, {"id": "B", "text": "Text 1 argues that electric vehicles have no environmental benefits, while Text 2 argues that ethanol has none."}, {"id": "C", "text": "Both texts conclude that internal combustion engines will soon disappear."}, {"id": "D", "text": "Text 2 explains how electric vehicles are manufactured, while Text 1 compares their range with that of ethanol-powered cars."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Electric vehicle" and "Ethanol fuel", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Electric_vehicle ; https://en.wikipedia.org/wiki/Ethanol_fuel', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT007', 'A', ARRAY['A']::TEXT[], 'Text 1 covers electric vehicles and credits lithium batteries with reviving interest in them. Text 2 covers ethanol, describing how it is produced, its use as a gasoline alternative and the environmental and economic concerns its production raises.', '{"B": "Text 1 calls electric vehicles zero-emission options, and Text 2 calls ethanol renewable even as it notes concerns.", "D": "Text 2 does not discuss vehicle manufacturing, and Text 1 makes no comparison with ethanol.", "C": "Neither text predicts the disappearance of internal combustion engines."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT008', 'HDSAT-RW-M17-CT008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Hard', 'multiple_choice', 'Text 1
An electric vehicle (EV) is a vehicle propelled mostly by electric power. EVs encompass electric cars and other electric road vehicles (buses, trucks and personal transporters) as well as other types of land vehicles, such as electric rail vehicles (trains, trams and monorails). It also includes electric watercraft (boats and submersibles), aircraft (fixed-wing and multirotors), and spacecraft.
EVs originated in the late 19th century. Electricity was among the preferred methods for powering early motor vehicles because it was quieter, provided comfort, and ease of operation. However, its limited range hindered mass adoption throughout the 20th century. Internal combustion engines were the dominant propulsion mechanisms for cars and trucks for about 100 years, although electricity-powered locomotion became commonplace in other vehicle types, such as overhead line-powered mass transit vehicles, as well as special purpose vehicles such as mobility scooters.
Since the late 20th century, technological advances in lithium batteries—which offer superior energy density and current output versus lead-acid batteries—have revived public interest as zero-emission vehicle options.

Text 2
Ethanol fuel is an alcohol-based fuel commonly produced by fermenting sugars from crops such as corn, sugarcane, and other biomass, although it can also be synthesized from petroleum derivatives. While it is the same type of alcohol as found in alcoholic beverages, it is most often used as an alternative to gasoline in transportation, either as a pure fuel or blended into gasoline mixtures as a biofuel additive, to reduce reliance on fossil fuels and lower greenhouse gas emissions. Ethanol fuel in Brazil and the United States dominate global ethanol production, together accounting for the majority of supply, and many countries mandate ethanol blending in automotive fuels.
Historically, ethanol has been used as a fuel since the early 20th century, with Brazil pioneering large-scale adoption during the 1970s energy crisis. Advances in flexible-fuel vehicle technology and government policies have expanded its use worldwide. Ethanol''s chemical composition (C2H5OH) allows it to burn cleanly, producing carbon dioxide and water, and its high octane rating makes it suitable for high-compression engines. Most ethanol is produced through microbial fermentation of sugars, followed by distillation and dehydration, though synthetic ethanol from ethylene remains a small share of global output.
Ethanol is considered a renewable energy source, but its production raises environmental and economic concerns.', 'Based on the texts, how would the author of Text 2 most likely respond to the claim in Text 1 that battery advances have made electric vehicles viable zero-emission options?', '[{"id": "A", "text": "By denying that lithium batteries improved the range of electric vehicles."}, {"id": "B", "text": "By noting that a fuel can be renewable and still raise environmental concerns during production."}, {"id": "C", "text": "By claiming that internal combustion engines are quieter than electric motors."}, {"id": "D", "text": "By arguing that ethanol produces no greenhouse gases when burned."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Electric vehicle" and "Ethanol fuel", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Electric_vehicle ; https://en.wikipedia.org/wiki/Ethanol_fuel', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT008', 'B', ARRAY['B']::TEXT[], 'Text 2 calls ethanol a renewable energy source while cautioning that its production raises environmental and economic concerns. That is a parallel caution: a fuel billed as environmentally preferable can still carry costs that the label does not capture.', '{"A": "Text 2 does not discuss lithium batteries or the range of electric vehicles.", "D": "Text 2 says ethanol burns to produce carbon dioxide and water, so it does not claim the fuel produces no greenhouse gases.", "C": "Text 1 states that electric power was quieter than the alternatives, and Text 2 makes no noise comparison."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT009', 'HDSAT-RW-M17-CT009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Easy', 'multiple_choice', 'Text 1
Urban sprawl (also known as suburban sprawl or urban encroachment) is defined as "the rapid expansion of the geographic extent of cities and towns, often characterized by low-density residential housing, single-use zoning, and increased reliance on the private automobile for transportation". Urban sprawl has been described as the unrestricted spread over large expanses of land around an urban area of housing, commercial development, and roads, with little concern for very dense urban planning.
Urban sprawl refers to a special form of urbanization, and it relates to the social and environmental consequences associated with such development. In modern times some suburban areas described as "sprawl" have less detached housing and higher density than the nearby core city. Medieval suburbs suffered from the loss of protection of city walls, before the advent of industrial warfare. Sometimes the urban areas described as the most "sprawling" are the most densely populated.
The modern disadvantages and costs of urban sprawl include increased travel time, transport costs, pollution, and destruction of the countryside. The revenue for building and maintaining urban infrastructure in these areas is gained mostly through property and sales taxes.

Text 2
New Urbanism is an urban design movement that promotes environmentally friendly habits by creating walkable neighbourhoods containing a wide range of housing and job types. It arose in the United States in the early 1980s, and has gradually influenced many aspects of real estate development, urban planning, and municipal land-use strategies. New Urbanism attempts to address the ills associated with urban sprawl and post-WWII suburban development.
New Urbanism is strongly influenced by urban design practices that were prominent until the rise of the automobile prior to World War II; it encompasses basic principles such as traditional neighborhood development (TND) and transit-oriented development (TOD). These concrete principles emerge from two  organizing concepts or goals: building a sense of community and the development of ecological practices.
New Urbanists support regional planning for open space; context-appropriate architecture and planning; adequate provision of infrastructure such as sporting facilities, libraries and community centres; and the balanced development of jobs and housing. They believe their strategies can reduce traffic congestion by encouraging the population to ride bikes, walk, or take the train. They also hope to increase the supply of affordable housing and rein in suburban sprawl.', 'Which choice best describes the relationship between the two texts?', '[{"id": "A", "text": "Text 2 offers a history of urban sprawl that Text 1 uses to propose a solution."}, {"id": "B", "text": "Text 1 advocates the principles of New Urbanism, while Text 2 describes the disadvantages of sprawl."}, {"id": "C", "text": "Text 1 defines a development pattern and lists its costs, while Text 2 describes a movement that aims to address those costs."}, {"id": "D", "text": "Both texts argue that low-density housing is the best way to reduce traffic congestion."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Urban sprawl" and "New Urbanism", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Urban_sprawl ; https://en.wikipedia.org/wiki/New_Urbanism', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT009', 'C', ARRAY['C']::TEXT[], 'Text 1 characterizes sprawl as low-density, single-use, automobile-dependent expansion and lists its disadvantages. Text 2 presents New Urbanism as a design movement that addresses the ills of sprawl through walkable neighborhoods and transit-oriented development.', '{"B": "The roles are reversed: Text 1 defines sprawl and its costs, and Text 2 describes New Urbanism.", "D": "Both texts criticize sprawl rather than endorse low-density housing; Text 2 promotes walkable, mixed-use neighborhoods.", "A": "Text 1 proposes no solution, and Text 2 does not offer a history of sprawl."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT010', 'HDSAT-RW-M17-CT010', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Medium', 'multiple_choice', 'Text 1
Urban sprawl (also known as suburban sprawl or urban encroachment) is defined as "the rapid expansion of the geographic extent of cities and towns, often characterized by low-density residential housing, single-use zoning, and increased reliance on the private automobile for transportation". Urban sprawl has been described as the unrestricted spread over large expanses of land around an urban area of housing, commercial development, and roads, with little concern for very dense urban planning.
Urban sprawl refers to a special form of urbanization, and it relates to the social and environmental consequences associated with such development. In modern times some suburban areas described as "sprawl" have less detached housing and higher density than the nearby core city. Medieval suburbs suffered from the loss of protection of city walls, before the advent of industrial warfare. Sometimes the urban areas described as the most "sprawling" are the most densely populated.
The modern disadvantages and costs of urban sprawl include increased travel time, transport costs, pollution, and destruction of the countryside. The revenue for building and maintaining urban infrastructure in these areas is gained mostly through property and sales taxes.

Text 2
New Urbanism is an urban design movement that promotes environmentally friendly habits by creating walkable neighbourhoods containing a wide range of housing and job types. It arose in the United States in the early 1980s, and has gradually influenced many aspects of real estate development, urban planning, and municipal land-use strategies. New Urbanism attempts to address the ills associated with urban sprawl and post-WWII suburban development.
New Urbanism is strongly influenced by urban design practices that were prominent until the rise of the automobile prior to World War II; it encompasses basic principles such as traditional neighborhood development (TND) and transit-oriented development (TOD). These concrete principles emerge from two  organizing concepts or goals: building a sense of community and the development of ecological practices.
New Urbanists support regional planning for open space; context-appropriate architecture and planning; adequate provision of infrastructure such as sporting facilities, libraries and community centres; and the balanced development of jobs and housing. They believe their strategies can reduce traffic congestion by encouraging the population to ride bikes, walk, or take the train. They also hope to increase the supply of affordable housing and rein in suburban sprawl.', 'Based on the texts, how would the author of Text 2 most likely respond to the claim in Text 1 that sprawl increases travel time, transport costs and pollution?', '[{"id": "A", "text": "By claiming that private automobiles are the only practical form of transport."}, {"id": "B", "text": "By proposing walkable, transit-oriented neighborhoods as a way to reduce those burdens."}, {"id": "C", "text": "By denying that sprawl has any environmental consequences."}, {"id": "D", "text": "By arguing that single-use zoning is essential to walkable communities."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Urban sprawl" and "New Urbanism", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Urban_sprawl ; https://en.wikipedia.org/wiki/New_Urbanism', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT010', 'B', ARRAY['B']::TEXT[], 'Text 2 states that New Urbanists believe their strategies can reduce traffic congestion by encouraging people to ride bikes, walk or take the train. Those strategies are offered as remedies for exactly the travel-related costs Text 1 attributes to sprawl.', '{"C": "Text 2 describes New Urbanism as addressing the ills of sprawl, so it does not deny those consequences.", "D": "Text 2 promotes mixed housing and job types, not single-use zoning, which Text 1 associates with sprawl.", "A": "Text 2 says New Urbanists believe traffic congestion can be reduced by encouraging biking, walking and trains, so it does not treat cars as the only option."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT011', 'HDSAT-RW-M17-CT011', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Medium', 'multiple_choice', 'Text 1
Social media are new media technologies that facilitate the creation, sharing and aggregation of content (such as ideas, interests, and other forms of expression) amongst virtual communities and networks. Common features include:

Online platforms enable users to create and share content and participate in social networking.
User-generated content such as text posts or comments, digital photos or videos, and data generated through online interactions.
Service specific profiles that are designed and maintained by the social media organization.
Social media helps the development of online social networks by connecting a user''s profile with those of other individuals or groups.
The term social in regard to media suggests platforms enable communal activity. Social media helps people connect and build networks. Users access social media through web-based or mobile applications.

Text 2
Digital divide is inequitable access to and use of digital technology, encompassing four interrelated dimensions: motivational, material, skills, and usage access.
The digital divide worsens inequality in access to information and resources.
According to 2026 data from the U.S. Census Bureau, a significant ''digital divide'' persists, with over 15.8 million Americans lacking access to high-speed broadband.
Students from low-income households often face limited access to reliable internet and digital devices, which negatively affects their educational opportunities.
In the Information Age, people without access to the Internet and other technology are at a disadvantage, for they are less able to connect with others, find and apply for jobs, shop, and learn.
People living in poverty, in insecure housing or who are homeless, elderly people, and those living in rural communities may have limited access to the Internet; in contrast, urban middle class people have easy access to the Internet. Another divide is between producers and consumers of Internet content, which could be a result of educational disparities. While social media use varies across age groups, a 2010 US study reported no racial divide.', 'Which choice best describes the relationship between the two texts?', '[{"id": "A", "text": "Both texts focus on how social media platforms are designed and maintained."}, {"id": "B", "text": "Text 1 argues that social media worsen inequality, while Text 2 argues that they reduce it."}, {"id": "C", "text": "Text 2 describes the history of social media, while Text 1 reports current broadband statistics."}, {"id": "D", "text": "Text 1 describes what social media allow users to do, while Text 2 explains that unequal access to digital technology can keep some people from those benefits."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Social media" and "Digital divide", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Social_media ; https://en.wikipedia.org/wiki/Digital_divide', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT011', 'D', ARRAY['D']::TEXT[], 'Text 1 explains that social media enable users to create, share and aggregate content and to build networks. Text 2 documents unequal access to digital technology and notes that people without reliable internet are less able to connect, find jobs, shop and learn.', '{"B": "Text 1 does not discuss inequality, and Text 2 says the digital divide worsens inequality rather than claiming social media reduce it.", "A": "Platform design is one feature listed in Text 1; Text 2 concerns access to technology, not platform design.", "C": "Text 2 offers no history of social media, and the broadband statistic appears in Text 2, not Text 1."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT012', 'HDSAT-RW-M17-CT012', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Hard', 'multiple_choice', 'Text 1
Social media are new media technologies that facilitate the creation, sharing and aggregation of content (such as ideas, interests, and other forms of expression) amongst virtual communities and networks. Common features include:

Online platforms enable users to create and share content and participate in social networking.
User-generated content such as text posts or comments, digital photos or videos, and data generated through online interactions.
Service specific profiles that are designed and maintained by the social media organization.
Social media helps the development of online social networks by connecting a user''s profile with those of other individuals or groups.
The term social in regard to media suggests platforms enable communal activity. Social media helps people connect and build networks. Users access social media through web-based or mobile applications.

Text 2
Digital divide is inequitable access to and use of digital technology, encompassing four interrelated dimensions: motivational, material, skills, and usage access.
The digital divide worsens inequality in access to information and resources.
According to 2026 data from the U.S. Census Bureau, a significant ''digital divide'' persists, with over 15.8 million Americans lacking access to high-speed broadband.
Students from low-income households often face limited access to reliable internet and digital devices, which negatively affects their educational opportunities.
In the Information Age, people without access to the Internet and other technology are at a disadvantage, for they are less able to connect with others, find and apply for jobs, shop, and learn.
People living in poverty, in insecure housing or who are homeless, elderly people, and those living in rural communities may have limited access to the Internet; in contrast, urban middle class people have easy access to the Internet. Another divide is between producers and consumers of Internet content, which could be a result of educational disparities. While social media use varies across age groups, a 2010 US study reported no racial divide.', 'Based on the texts, how would the author of Text 2 most likely respond to the claim in Text 1 that social media help people connect and build networks?', '[{"id": "A", "text": "By arguing that social media platforms prevent users from forming communities."}, {"id": "B", "text": "By claiming that all Americans now have high-speed broadband."}, {"id": "C", "text": "By noting that a 2010 study found no racial divide in social media use."}, {"id": "D", "text": "By observing that people without reliable internet access are less able to participate in those networks."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Social media" and "Digital divide", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Social_media ; https://en.wikipedia.org/wiki/Digital_divide', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT012', 'D', ARRAY['D']::TEXT[], 'Text 2 stresses that access is unequal: millions lack broadband, and low-income students often lack reliable internet and devices. That qualifies Text 1''s claim by indicating that the networking benefits are available only to those who can get online.', '{"A": "Text 2 does not say social media prevent community; it identifies barriers to access.", "B": "Text 2 reports that over 15.8 million Americans lack high-speed broadband, which contradicts universal access.", "C": "The 2010 study is a detail about racial differences in use, not a response to whether social media help people connect."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT013', 'HDSAT-RW-M17-CT013', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Medium', 'multiple_choice', 'Text 1
A zoo (short for zoological garden; also called a zoological park, animal park, or menagerie) is a facility where animals are kept within enclosures for exhibition and often bred for conservation purposes. Zoos vary greatly in size, ranging from small urban enclosures of a few acres to massive open-range and natural-habitat reserves spanning thousands of acres.
The term zoological garden refers to zoology, the study of animals. The term is derived from the Ancient Greek ζῷον, zōion, ''animal'', and the suffix -λογία, -logia, ''study of''. The abbreviation zoo was first used of the London Zoological Gardens, which was opened for scientific study in 1828, and to the public in 1847. The first modern zoo was the Tierpark Hagenbeck by Carl Hagenbeck in Germany. In the United States alone, zoos are visited by over 181 million people annually.
However, animal welfare organizations have expressed criticism of zoos and the conditions in which animals are kept.

Text 2
Animal welfare is the quality of life and overall well-being of animals. Formal standards of animal welfare vary between contexts, but are debated mostly by animal welfare groups, legislators, and academics. Animal welfare science uses measures such as longevity, disease, immunosuppression, behavior, physiology, and reproduction, although there is debate about which of these best indicate animal welfare.
Respect for animal welfare is often based on the belief that nonhuman animals are sentient and that consideration should be given to their well-being or suffering, especially when they are under the care of humans. These concerns can include how animals are slaughtered for food, how they are used in scientific research, how they are kept (as pets, in zoos, farms, circuses, etc.), and how human activities affect the welfare and survival of wild species.
There are two forms of criticism of the concept of animal welfare, coming from diametrically opposite positions. One view, held by some thinkers in history, holds that humans have no duties of any kind to animals. The other view is based on the animal rights position that animals should not be regarded as objects and any use of animals by humans is unacceptable.', 'Which choice best describes the relationship between the two texts?', '[{"id": "A", "text": "Text 1 describes zoos and notes criticism of them, while Text 2 explains a framework for evaluating the well-being of animals kept in settings such as zoos."}, {"id": "B", "text": "Both texts rely on the claim that animals cannot experience suffering."}, {"id": "C", "text": "Text 2 provides attendance figures that Text 1 uses to justify keeping animals in enclosures."}, {"id": "D", "text": "Text 1 argues that zoos should be abolished, while Text 2 defends their conservation work."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Zoo" and "Animal welfare", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Zoo ; https://en.wikipedia.org/wiki/Animal_welfare', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT013', 'A', ARRAY['A']::TEXT[], 'Text 1 defines zoos, gives their scale and attendance, and mentions criticism of animal conditions. Text 2 defines animal welfare, lists the measures scientists use to assess it and identifies zoos as one setting where welfare concerns arise.', '{"D": "Text 1 reports that welfare organizations have criticized zoos but does not call for abolishing them, and Text 2 does not defend conservation work.", "B": "Text 2 says respect for animal welfare is often based on the belief that animals are sentient, the opposite of the claim.", "C": "The attendance figure appears in Text 1, and Text 2 supplies no attendance data."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT014', 'HDSAT-RW-M17-CT014', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Hard', 'multiple_choice', 'Text 1
A zoo (short for zoological garden; also called a zoological park, animal park, or menagerie) is a facility where animals are kept within enclosures for exhibition and often bred for conservation purposes. Zoos vary greatly in size, ranging from small urban enclosures of a few acres to massive open-range and natural-habitat reserves spanning thousands of acres.
The term zoological garden refers to zoology, the study of animals. The term is derived from the Ancient Greek ζῷον, zōion, ''animal'', and the suffix -λογία, -logia, ''study of''. The abbreviation zoo was first used of the London Zoological Gardens, which was opened for scientific study in 1828, and to the public in 1847. The first modern zoo was the Tierpark Hagenbeck by Carl Hagenbeck in Germany. In the United States alone, zoos are visited by over 181 million people annually.
However, animal welfare organizations have expressed criticism of zoos and the conditions in which animals are kept.

Text 2
Animal welfare is the quality of life and overall well-being of animals. Formal standards of animal welfare vary between contexts, but are debated mostly by animal welfare groups, legislators, and academics. Animal welfare science uses measures such as longevity, disease, immunosuppression, behavior, physiology, and reproduction, although there is debate about which of these best indicate animal welfare.
Respect for animal welfare is often based on the belief that nonhuman animals are sentient and that consideration should be given to their well-being or suffering, especially when they are under the care of humans. These concerns can include how animals are slaughtered for food, how they are used in scientific research, how they are kept (as pets, in zoos, farms, circuses, etc.), and how human activities affect the welfare and survival of wild species.
There are two forms of criticism of the concept of animal welfare, coming from diametrically opposite positions. One view, held by some thinkers in history, holds that humans have no duties of any kind to animals. The other view is based on the animal rights position that animals should not be regarded as objects and any use of animals by humans is unacceptable.', 'Based on the texts, how would the author of Text 2 most likely respond to the claim in Text 1 that zoos often breed animals for conservation purposes?', '[{"id": "A", "text": "By raising the question of whether conservation breeding justifies the conditions in which zoo animals are kept."}, {"id": "B", "text": "By denying that zoos play any role in breeding animals."}, {"id": "C", "text": "By arguing that visitors, not enclosure conditions, determine animal welfare."}, {"id": "D", "text": "By claiming that animal welfare cannot be studied scientifically."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Zoo" and "Animal welfare", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Zoo ; https://en.wikipedia.org/wiki/Animal_welfare', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT014', 'A', ARRAY['A']::TEXT[], 'Text 2 identifies how animals are kept in zoos as a welfare concern and notes that some critics regard any human use of animals as unacceptable. That framework makes conservation breeding a justification to be weighed against the animals'' conditions, not a settled answer.', '{"B": "Text 2 does not deny that zoos breed animals; it asks how animals in zoos and similar settings are kept.", "C": "Text 2 treats how animals are kept as a central welfare concern, not something visitors determine.", "D": "Text 2 describes scientific measures of welfare such as longevity, disease and behavior, though it notes debate about which measures are best."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT015', 'HDSAT-RW-M17-CT015', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Medium', 'multiple_choice', 'Text 1
Space exploration is the physical investigation of outer space by uncrewed robotic space probes and through human spaceflight.
While the observation of objects in space, known as astronomy, predates reliable recorded history, it was the development of large and relatively efficient rockets during the mid-twentieth century that allowed physical space exploration to become a reality. Common rationales for exploring space include advancing scientific research, national prestige, uniting different countries, ensuring the future survival of humanity, and developing military and strategic advantages against other countries.
The early era of space exploration was driven by a "Space Race" in which the Soviet Union and the United States vied to demonstrate their technological superiority. Landmarks of this era include the launch of the first human-made object to orbit Earth, the Soviet Union''s Sputnik 1, on 4 October 1957, and the first Moon landing by the American Apollo 11 mission on 20 July 1969. The Soviet space program achieved many of the first milestones, including the first living being in orbit in 1957, the first human spaceflight (Yuri Gagarin aboard Vostok 1) in 1961, the first spacewalk (by Alexei Leonov) on 18 March 1965, the first automatic landing on another celestial body in 1966, and the launch of the first space station (Salyut 1) in 1971. 
In the 1970s, focus shifted from one-off flights to renewable hardware, such as the Space Shuttle program, and from competition to cooperation, the foremost example being the International Space Station (ISS), built between 1998 and 2011.
The 2000s brought advancements in the national space-exploration programs of China, the European Union, Japan, and India.

Text 2
Space colonization, or extraterrestrial colonization, is the establishment of human settlements or colonies in outer space and on astronomical bodies. The concept, in its broadest sense, has been applied to any permanent human presence in space, such as a space habitat or other extraterrestrial settlements. It may involve notions of territorial occupation, resource control for economic or military purposes, such as extraterrestrial mining, or military practice ground as shown in a space force.
Making territorial claims in space is under prohibition by international space law (ISL), defining space as a common heritage. International space law has had the goal to prevent colonial claims and militarization of space, and has advocated the installation of international regimes to regulate access to and sharing of space, particularly for specific locations such as the limited space of geostationary orbit or the Moon. To date, no permanent space settlement other than temporary space habitats have been established, nor has any extraterrestrial territory or land been internationally claimed. Currently there are also no plans for building a space colony by any government. However, many proposals, speculations, and designs, particularly for extraterrestrial settlements have been made through the years, and a considerable number of space colonization advocates and groups are active.', 'Which choice best describes the relationship between the two texts?', '[{"id": "A", "text": "Text 1 argues that space exploration has ended, while Text 2 describes its recent accomplishments."}, {"id": "B", "text": "Both texts treat the establishment of permanent space colonies as an accomplished fact."}, {"id": "C", "text": "Text 1 describes reasons for and milestones of exploring space, while Text 2 discusses proposals to settle space and the legal limits on such settlements."}, {"id": "D", "text": "Text 2 explains how rockets were developed, while Text 1 describes international space law."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Space exploration" and "Space colonization", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Space_exploration ; https://en.wikipedia.org/wiki/Space_colonization', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT015', 'C', ARRAY['C']::TEXT[], 'Text 1 covers the history and rationales of space exploration, from Sputnik and Apollo to the International Space Station. Text 2 covers the idea of colonizing space, noting that international law prohibits territorial claims and that no permanent settlement or government plan exists.', '{"A": "Text 1 describes continuing programs and cooperation, not an end to exploration.", "B": "Text 2 states that no permanent space settlement has been established and no government has plans for one.", "D": "Rocket development is described in Text 1, and international space law is discussed in Text 2."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT016', 'HDSAT-RW-M17-CT016', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Hard', 'multiple_choice', 'Text 1
Space exploration is the physical investigation of outer space by uncrewed robotic space probes and through human spaceflight.
While the observation of objects in space, known as astronomy, predates reliable recorded history, it was the development of large and relatively efficient rockets during the mid-twentieth century that allowed physical space exploration to become a reality. Common rationales for exploring space include advancing scientific research, national prestige, uniting different countries, ensuring the future survival of humanity, and developing military and strategic advantages against other countries.
The early era of space exploration was driven by a "Space Race" in which the Soviet Union and the United States vied to demonstrate their technological superiority. Landmarks of this era include the launch of the first human-made object to orbit Earth, the Soviet Union''s Sputnik 1, on 4 October 1957, and the first Moon landing by the American Apollo 11 mission on 20 July 1969. The Soviet space program achieved many of the first milestones, including the first living being in orbit in 1957, the first human spaceflight (Yuri Gagarin aboard Vostok 1) in 1961, the first spacewalk (by Alexei Leonov) on 18 March 1965, the first automatic landing on another celestial body in 1966, and the launch of the first space station (Salyut 1) in 1971. 
In the 1970s, focus shifted from one-off flights to renewable hardware, such as the Space Shuttle program, and from competition to cooperation, the foremost example being the International Space Station (ISS), built between 1998 and 2011.
The 2000s brought advancements in the national space-exploration programs of China, the European Union, Japan, and India.

Text 2
Space colonization, or extraterrestrial colonization, is the establishment of human settlements or colonies in outer space and on astronomical bodies. The concept, in its broadest sense, has been applied to any permanent human presence in space, such as a space habitat or other extraterrestrial settlements. It may involve notions of territorial occupation, resource control for economic or military purposes, such as extraterrestrial mining, or military practice ground as shown in a space force.
Making territorial claims in space is under prohibition by international space law (ISL), defining space as a common heritage. International space law has had the goal to prevent colonial claims and militarization of space, and has advocated the installation of international regimes to regulate access to and sharing of space, particularly for specific locations such as the limited space of geostationary orbit or the Moon. To date, no permanent space settlement other than temporary space habitats have been established, nor has any extraterrestrial territory or land been internationally claimed. Currently there are also no plans for building a space colony by any government. However, many proposals, speculations, and designs, particularly for extraterrestrial settlements have been made through the years, and a considerable number of space colonization advocates and groups are active.', 'Based on the texts, how would the author of Text 2 most likely respond to the claim in Text 1 that ensuring humanity''s future survival is a reason to explore space?', '[{"id": "A", "text": "By noting that permanent settlements would face legal prohibitions and that no government currently plans one."}, {"id": "B", "text": "By arguing that space exploration has no scientific value."}, {"id": "C", "text": "By disputing that any country has ever sent a probe into space."}, {"id": "D", "text": "By claiming that international law encourages territorial claims in space."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Space exploration" and "Space colonization", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Space_exploration ; https://en.wikipedia.org/wiki/Space_colonization', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT016', 'A', ARRAY['A']::TEXT[], 'Text 2 explains that claims to territory in space are prohibited and that no government currently plans a colony. Those are practical and legal obstacles that anyone pursuing survival-through-settlement would have to address.', '{"C": "Text 1 lists numerous milestones, including Sputnik 1, and Text 2 does not dispute them.", "D": "Text 2 says international space law prohibits territorial claims and aims to prevent colonial claims.", "B": "Text 2 does not assess the scientific value of exploration; it focuses on settlement and law."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT017', 'HDSAT-RW-M17-CT017', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Medium', 'multiple_choice', 'Text 1
A minimum wage is the lowest remuneration that employers can legally pay their employees—the price floor below which employees may not sell their labor. Most countries had introduced minimum wage legislation by the end of the 20th century. Because minimum wages increase the cost of labor, companies often try to avoid minimum wage laws by using gig workers, by moving labor to locations with lower or nonexistent minimum wages, or by automating job functions. Minimum wage policies can vary significantly between countries or even within a country, with different regions, sectors, or age groups having their own minimum wage rates. These variations are often influenced by the cost of living, regional economic conditions, and industry-specific factors.

The movement for minimum wages was initially motivated by a desire to stop the exploitation of workers in sweatshops by employers who were thought to have unfair bargaining power over them. Over time, minimum wages came to be seen as a way to help lower-income families. Modern national laws enforcing compulsory union membership and prescribing minimum wages for members were first passed in New Zealand in 1894.

Text 2
Universal basic income (UBI) is a social welfare proposal in which all members of a given population regularly receive a minimum income in the form of an unconditional transfer payment, i.e., without a means test or need to perform work. In contrast, a guaranteed minimum income (GMI) is paid only to those who do not already receive an income that is enough to live on. A UBI would be received independently of any other income. If the level is sufficient to meet a person''s basic needs (i.e., at or above the poverty line), it is considered a full basic income; if it is less than that amount, it is called a partial basic income. As of 2026, no country has implemented a full UBI system, but two countries—Mongolia and Iran—have or had a partial UBI, Mongolia from 2010 to 2012, and Iran still to this day. There have been numerous pilot projects, and the idea is discussed in many countries. Some have labelled UBI as utopian due to its historical origin.
There are several welfare arrangements that can be considered similar to basic income, although they are not unconditional.', 'Which choice best describes the relationship between the two texts?', '[{"id": "A", "text": "Text 1 argues for replacing minimum wages with basic income, while Text 2 argues against the idea."}, {"id": "B", "text": "Text 1 describes a wage floor and how employers respond to it, while Text 2 describes an unconditional payment that is not tied to employment."}, {"id": "C", "text": "Text 2 reports that every country has adopted a full basic income."}, {"id": "D", "text": "Both texts focus on the history of labor legislation in New Zealand."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Minimum wage" and "Universal basic income", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Minimum_wage ; https://en.wikipedia.org/wiki/Universal_basic_income', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT017', 'B', ARRAY['B']::TEXT[], 'Text 1 explains the minimum wage as a legally enforced price floor and notes that employers try to avoid it through gig work, relocation or automation. Text 2 defines universal basic income as an unconditional transfer paid regardless of other income or work.', '{"A": "Text 1 does not propose a basic income, and Text 2 neither advocates nor rejects one.", "D": "New Zealand is mentioned only in Text 1, and Text 2 offers no labor history.", "C": "Text 2 states that no country has implemented a full basic income."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT018', 'HDSAT-RW-M17-CT018', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Hard', 'multiple_choice', 'Text 1
A minimum wage is the lowest remuneration that employers can legally pay their employees—the price floor below which employees may not sell their labor. Most countries had introduced minimum wage legislation by the end of the 20th century. Because minimum wages increase the cost of labor, companies often try to avoid minimum wage laws by using gig workers, by moving labor to locations with lower or nonexistent minimum wages, or by automating job functions. Minimum wage policies can vary significantly between countries or even within a country, with different regions, sectors, or age groups having their own minimum wage rates. These variations are often influenced by the cost of living, regional economic conditions, and industry-specific factors.

The movement for minimum wages was initially motivated by a desire to stop the exploitation of workers in sweatshops by employers who were thought to have unfair bargaining power over them. Over time, minimum wages came to be seen as a way to help lower-income families. Modern national laws enforcing compulsory union membership and prescribing minimum wages for members were first passed in New Zealand in 1894.

Text 2
Universal basic income (UBI) is a social welfare proposal in which all members of a given population regularly receive a minimum income in the form of an unconditional transfer payment, i.e., without a means test or need to perform work. In contrast, a guaranteed minimum income (GMI) is paid only to those who do not already receive an income that is enough to live on. A UBI would be received independently of any other income. If the level is sufficient to meet a person''s basic needs (i.e., at or above the poverty line), it is considered a full basic income; if it is less than that amount, it is called a partial basic income. As of 2026, no country has implemented a full UBI system, but two countries—Mongolia and Iran—have or had a partial UBI, Mongolia from 2010 to 2012, and Iran still to this day. There have been numerous pilot projects, and the idea is discussed in many countries. Some have labelled UBI as utopian due to its historical origin.
There are several welfare arrangements that can be considered similar to basic income, although they are not unconditional.', 'Based on the texts, how would the author of Text 2 most likely respond to the claim in Text 1 that employers often try to avoid minimum wage laws?', '[{"id": "A", "text": "By noting that Mongolia and Iran pay a full basic income."}, {"id": "B", "text": "By claiming that employers never adjust hiring in response to wage laws."}, {"id": "C", "text": "By suggesting that an unconditional payment to all people would not give employers the same incentive to circumvent it."}, {"id": "D", "text": "By arguing that a basic income is simply another name for a minimum wage."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Minimum wage" and "Universal basic income", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Minimum_wage ; https://en.wikipedia.org/wiki/Universal_basic_income', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT018', 'C', ARRAY['C']::TEXT[], 'The avoidance behavior in Text 1 arises because a minimum wage raises the cost of employing someone. Text 2''s definition of basic income as an unconditional transfer to all people, independent of employment, implies that employers would have no wage floor to circumvent.', '{"D": "Text 2 defines basic income as unconditional and not requiring work, which distinguishes it from a wage floor.", "B": "Text 1 states that companies often try to avoid minimum wage laws, and Text 2 does not dispute that behavior.", "A": "Text 2 describes the payments in Mongolia and Iran as partial, not full."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT019', 'HDSAT-RW-M17-CT019', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Medium', 'multiple_choice', 'Text 1
Artificial intelligence (AI) is the capability of computational systems to perform tasks typically associated with human intelligence, such as learning, reasoning, problem-solving, perception, and decision-making. It is also a field of research spanning computer science, engineering, and mathematics that develops and studies methods and software enabling machines to perceive their environment and use learning and intelligence to take actions that maximise their chances of achieving defined goals.
Prominent applications of AI include advanced web search engines, chatbots, virtual assistants, autonomous vehicles, play and analysis in strategy games (e.g., chess and Go), and content generation (e.g., text, images, audio, and videos).
The traditional goals of AI research include learning, reasoning, knowledge representation, planning, natural language processing, and perception, as well as support for robotics. To reach these goals, AI researchers use techniques including state space search and mathematical optimisation, formal logic, artificial neural networks, and methods based on statistics, operations research, and economics. AI also draws upon psychology, linguistics, philosophy, neuroscience, and other fields. Some companies, such as OpenAI, Google DeepMind, and Meta, aim to create artificial general intelligence (AGI)—AI that can complete nearly any cognitive task at least as well as a human.
Artificial intelligence was founded as an academic discipline in 1956.

Text 2
Automation describes a wide range of technologies that reduce human intervention in processes, mainly by predetermining decision criteria, subprocess relationships, and related actions, as well as embodying those predeterminations in machines. Automation has been achieved by various means including mechanical, hydraulic, pneumatic, electrical, electronic devices, and computers, usually in combination. Complicated systems, such as modern factories, airplanes, and ships typically use combinations of all of these techniques. The benefits of automation includes labor savings, reducing waste, savings in electricity costs, savings in material costs, and improvements to quality, accuracy, and precision.
Automation includes the use of various equipment and control systems such as machinery, processes in factories, boilers, and heat-treating ovens, switching on telephone networks, steering, stabilization of ships, aircraft and other applications and vehicles with reduced human intervention. Examples range from a household thermostat controlling a boiler to a large industrial control system with tens of thousands of input measurements and output control signals.
In the simplest type of an automatic control loop, a controller compares a measured value of a process with a desired set value and processes the resulting error signal to change some input to the process, in such a way that the process stays at its set point despite disturbances. This closed-loop control is an application of negative feedback to a system.', 'Which choice best describes the relationship between the two texts?', '[{"id": "A", "text": "Text 2 lists applications of AI, while Text 1 explains closed-loop control."}, {"id": "B", "text": "Text 1 argues that automation has replaced artificial intelligence, while Text 2 argues the reverse."}, {"id": "C", "text": "Text 1 defines artificial intelligence as a capability and field of research, while Text 2 describes automation as a set of technologies that reduce human intervention."}, {"id": "D", "text": "Both texts claim that general intelligence has already been achieved by machines."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Artificial intelligence" and "Automation", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Artificial_intelligence ; https://en.wikipedia.org/wiki/Automation', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT019', 'C', ARRAY['C']::TEXT[], 'Text 1 defines AI through tasks associated with human intelligence and lists its applications and research goals. Text 2 defines automation as technologies that predetermine decisions and actions in machines, illustrated by devices from thermostats to industrial control systems.', '{"B": "Neither text claims one field replaced the other; they define different concepts.", "D": "Text 1 says some companies aim to create artificial general intelligence, not that it exists, and Text 2 does not mention general intelligence.", "A": "The applications appear in Text 1, and closed-loop control appears in Text 2."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT020', 'HDSAT-RW-M17-CT020', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Hard', 'multiple_choice', 'Text 1
Artificial intelligence (AI) is the capability of computational systems to perform tasks typically associated with human intelligence, such as learning, reasoning, problem-solving, perception, and decision-making. It is also a field of research spanning computer science, engineering, and mathematics that develops and studies methods and software enabling machines to perceive their environment and use learning and intelligence to take actions that maximise their chances of achieving defined goals.
Prominent applications of AI include advanced web search engines, chatbots, virtual assistants, autonomous vehicles, play and analysis in strategy games (e.g., chess and Go), and content generation (e.g., text, images, audio, and videos).
The traditional goals of AI research include learning, reasoning, knowledge representation, planning, natural language processing, and perception, as well as support for robotics. To reach these goals, AI researchers use techniques including state space search and mathematical optimisation, formal logic, artificial neural networks, and methods based on statistics, operations research, and economics. AI also draws upon psychology, linguistics, philosophy, neuroscience, and other fields. Some companies, such as OpenAI, Google DeepMind, and Meta, aim to create artificial general intelligence (AGI)—AI that can complete nearly any cognitive task at least as well as a human.
Artificial intelligence was founded as an academic discipline in 1956.

Text 2
Automation describes a wide range of technologies that reduce human intervention in processes, mainly by predetermining decision criteria, subprocess relationships, and related actions, as well as embodying those predeterminations in machines. Automation has been achieved by various means including mechanical, hydraulic, pneumatic, electrical, electronic devices, and computers, usually in combination. Complicated systems, such as modern factories, airplanes, and ships typically use combinations of all of these techniques. The benefits of automation includes labor savings, reducing waste, savings in electricity costs, savings in material costs, and improvements to quality, accuracy, and precision.
Automation includes the use of various equipment and control systems such as machinery, processes in factories, boilers, and heat-treating ovens, switching on telephone networks, steering, stabilization of ships, aircraft and other applications and vehicles with reduced human intervention. Examples range from a household thermostat controlling a boiler to a large industrial control system with tens of thousands of input measurements and output control signals.
In the simplest type of an automatic control loop, a controller compares a measured value of a process with a desired set value and processes the resulting error signal to change some input to the process, in such a way that the process stays at its set point despite disturbances. This closed-loop control is an application of negative feedback to a system.', 'Based on the texts, how would the author of Text 2 most likely respond to the claim in Text 1 that some companies aim to build systems that can complete nearly any cognitive task as well as a human?', '[{"id": "A", "text": "By noting that many automated systems reduce human intervention without possessing general intelligence."}, {"id": "B", "text": "By arguing that automation requires a system to match human cognition."}, {"id": "C", "text": "By denying that any computational system can perform tasks associated with human intelligence."}, {"id": "D", "text": "By claiming that thermostats are examples of artificial general intelligence."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Artificial intelligence" and "Automation", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Artificial_intelligence ; https://en.wikipedia.org/wiki/Automation', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT020', 'A', ARRAY['A']::TEXT[], 'Text 2 characterizes automation as predetermining decision criteria and embodying them in machines, with examples ranging from a household thermostat to large control systems. None of those examples requires the general cognitive ability Text 1 describes as a goal.', '{"C": "Text 2 does not deny that computers can perform intelligent tasks; it describes what automation accomplishes.", "B": "Text 2''s examples, such as a thermostat controlling a boiler, show automation operating without human-like cognition.", "D": "Text 2 presents a thermostat as the simplest control loop, not as general intelligence."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT021', 'HDSAT-RW-M17-CT021', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Medium', 'multiple_choice', 'Text 1
Recycling is the process of converting waste materials into new materials and objects. This concept often includes the recovery of energy from waste materials. The recyclability of a material depends on its ability to reacquire the properties it had in its original state. It is an alternative to "conventional" waste disposal that can save material and help lower greenhouse gas emissions. It can also prevent the waste of potentially useful materials and reduce the consumption of fresh raw materials, reducing energy use, air pollution (from incineration) and water pollution (from landfilling).
Recycling is a key component of modern waste reduction and represents the third step in the "Reduce, Reuse, and Recycle" waste hierarchy, contributing to environmental sustainability and resource conservation. It promotes environmental sustainability by removing raw material input and redirecting waste output in the economic system. There are some ISO standards related to recycling, such as ISO 15270:2008 for plastics waste and ISO 14001:2015 for environmental management control of recycling practice.

Text 2
Incineration is a waste treatment process that involves the combustion of substances contained in waste materials. Industrial plants for waste incineration are commonly referred to as waste-to-energy facilities. Incineration and other high-temperature waste treatment systems are described as "thermal treatment". Incineration of waste materials converts the waste into ash, flue gas and heat. The ash is mostly formed by the inorganic constituents of the waste and may take the form of solid lumps or particulates carried by the flue gas. The flue gases must be cleaned of gaseous and particulate pollutants before they are dispersed into the atmosphere. In some cases, the heat that is generated by incineration can be used to generate electric power.
Incineration with energy recovery is one of several waste-to-energy technologies such as gasification, pyrolysis and anaerobic digestion.', 'Which choice best describes the relationship between the two texts?', '[{"id": "A", "text": "Text 1 argues that incineration is a form of recycling, while Text 2 argues that it is not."}, {"id": "B", "text": "Text 1 presents recycling as an alternative to disposal methods and notes incineration''s air pollution, while Text 2 explains how incineration converts waste into ash, gas and heat."}, {"id": "C", "text": "Text 2 describes the recycling process, while Text 1 describes the chemistry of combustion."}, {"id": "D", "text": "Both texts recommend burying waste in landfills rather than burning it."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Recycling" and "Incineration", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Recycling ; https://en.wikipedia.org/wiki/Incineration', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT021', 'B', ARRAY['B']::TEXT[], 'Text 1 defines recycling and credits it with reducing energy use and air pollution from incineration. Text 2 explains what incineration does: it burns waste, produces ash, flue gas and heat, and can generate electric power.', '{"A": "Text 1 mentions energy recovery as part of recycling but does not claim incineration is recycling, and Text 2 does not address that question.", "D": "Neither text recommends landfilling; Text 1 notes water pollution from landfills.", "C": "The processes are reversed: Text 1 concerns recycling, and Text 2 concerns combustion."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT022', 'HDSAT-RW-M17-CT022', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Hard', 'multiple_choice', 'Text 1
Recycling is the process of converting waste materials into new materials and objects. This concept often includes the recovery of energy from waste materials. The recyclability of a material depends on its ability to reacquire the properties it had in its original state. It is an alternative to "conventional" waste disposal that can save material and help lower greenhouse gas emissions. It can also prevent the waste of potentially useful materials and reduce the consumption of fresh raw materials, reducing energy use, air pollution (from incineration) and water pollution (from landfilling).
Recycling is a key component of modern waste reduction and represents the third step in the "Reduce, Reuse, and Recycle" waste hierarchy, contributing to environmental sustainability and resource conservation. It promotes environmental sustainability by removing raw material input and redirecting waste output in the economic system. There are some ISO standards related to recycling, such as ISO 15270:2008 for plastics waste and ISO 14001:2015 for environmental management control of recycling practice.

Text 2
Incineration is a waste treatment process that involves the combustion of substances contained in waste materials. Industrial plants for waste incineration are commonly referred to as waste-to-energy facilities. Incineration and other high-temperature waste treatment systems are described as "thermal treatment". Incineration of waste materials converts the waste into ash, flue gas and heat. The ash is mostly formed by the inorganic constituents of the waste and may take the form of solid lumps or particulates carried by the flue gas. The flue gases must be cleaned of gaseous and particulate pollutants before they are dispersed into the atmosphere. In some cases, the heat that is generated by incineration can be used to generate electric power.
Incineration with energy recovery is one of several waste-to-energy technologies such as gasification, pyrolysis and anaerobic digestion.', 'Based on the texts, how would the author of Text 2 most likely respond to the claim in Text 1 that recycling reduces air pollution from incineration?', '[{"id": "A", "text": "By noting that incineration''s flue gases can be cleaned of pollutants before they are released."}, {"id": "B", "text": "By arguing that recycling increases the amount of waste sent to landfills."}, {"id": "C", "text": "By denying that incineration produces any flue gas."}, {"id": "D", "text": "By claiming that incineration generates no usable heat."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Recycling" and "Incineration", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Recycling ; https://en.wikipedia.org/wiki/Incineration', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT022', 'A', ARRAY['A']::TEXT[], 'Text 1 treats incineration as a source of air pollution that recycling can reduce. Text 2 acknowledges that incineration produces flue gas but adds that the gas must be cleaned of pollutants before release, which identifies a factor that can limit the pollution Text 1 attributes to the process.', '{"C": "Text 2 states that incineration produces flue gas that must be cleaned.", "B": "Text 2 does not discuss recycling''s effect on landfill volumes.", "D": "Text 2 says the heat generated by incineration can be used to generate electric power."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT023', 'HDSAT-RW-M17-CT023', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Easy', 'multiple_choice', 'Text 1
Homework is a set of tasks assigned to students by their teachers to be completed at home. Common homework assignments may include required reading, a writing or typing project, math problems to be completed, information to be reviewed before a test, or other skills to be practiced.
The effects of homework are debated. Generally speaking, homework does not improve academic performance among young children. Homework may improve academic skills among older students, especially lower-achieving students. However, homework also creates stress for students and parents, and reduces the amount of time that students can spend in other activities.

Text 2
Unschooling is a practice of self-driven informal learning characterized by a lesson-free and curriculum-free implementation of homeschooling. Unschooling encourages exploration of activities initiated by the children themselves, under the belief that the more personal learning is, the more meaningful, well-understood, and therefore useful it is to the child.
The term unschooling was coined in the 1970s and used by educator John Holt, who is widely regarded as the father of unschooling. Unschooling is often seen as a subset of homeschooling, the key difference lying in the use of an external or individual curriculum. Homeschooling, in its many variations, has been the subject of public debate.
Critics of unschooling express concerns that unschooled children will be neglected by parents who may not be capable of sustaining a proper educational environment, and the child might lack the social skills, structure, discipline, and motivation of their schooled peers. Critics also worry that unschooled children will be unable to cope with uncomfortable or challenging situations. Some studies suggest that children who have participated in unschooling may experience academic underdevelopment.', 'Which choice best describes the relationship between the two texts?', '[{"id": "A", "text": "Text 2 provides a history of homework, while Text 1 describes the origins of unschooling."}, {"id": "B", "text": "Text 1 reviews evidence about tasks students are assigned to do at home, while Text 2 describes an approach in which children direct their own learning without a curriculum."}, {"id": "C", "text": "Text 1 argues that homework is essential for young children, while Text 2 defends assigned lessons."}, {"id": "D", "text": "Both texts report that homework improves academic performance at every age."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Homework" and "Unschooling", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Homework ; https://en.wikipedia.org/wiki/Unschooling', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT023', 'B', ARRAY['B']::TEXT[], 'Text 1 summarizes research on homework''s mixed effects and its costs in stress and time. Text 2 describes unschooling, a lesson-free and curriculum-free practice in which children''s own interests drive learning.', '{"C": "Text 1 reports that homework generally does not improve performance among young children, and Text 2 describes lesson-free learning rather than defending assignments.", "D": "Text 1 says homework may help older students, not every age, and Text 2 makes no claim about homework''s effects.", "A": "The history of unschooling appears in Text 2, and Text 1 offers no history of homework."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CT024', 'HDSAT-RW-M17-CT024', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Hard', 'multiple_choice', 'Text 1
Homework is a set of tasks assigned to students by their teachers to be completed at home. Common homework assignments may include required reading, a writing or typing project, math problems to be completed, information to be reviewed before a test, or other skills to be practiced.
The effects of homework are debated. Generally speaking, homework does not improve academic performance among young children. Homework may improve academic skills among older students, especially lower-achieving students. However, homework also creates stress for students and parents, and reduces the amount of time that students can spend in other activities.

Text 2
Unschooling is a practice of self-driven informal learning characterized by a lesson-free and curriculum-free implementation of homeschooling. Unschooling encourages exploration of activities initiated by the children themselves, under the belief that the more personal learning is, the more meaningful, well-understood, and therefore useful it is to the child.
The term unschooling was coined in the 1970s and used by educator John Holt, who is widely regarded as the father of unschooling. Unschooling is often seen as a subset of homeschooling, the key difference lying in the use of an external or individual curriculum. Homeschooling, in its many variations, has been the subject of public debate.
Critics of unschooling express concerns that unschooled children will be neglected by parents who may not be capable of sustaining a proper educational environment, and the child might lack the social skills, structure, discipline, and motivation of their schooled peers. Critics also worry that unschooled children will be unable to cope with uncomfortable or challenging situations. Some studies suggest that children who have participated in unschooling may experience academic underdevelopment.', 'Based on the texts, how would the author of Text 2 most likely respond to the claim in Text 1 that homework reduces the time students can spend on other activities?', '[{"id": "A", "text": "By arguing that learning initiated by children themselves is more meaningful than work assigned to them."}, {"id": "B", "text": "By denying that children can learn outside formal lessons."}, {"id": "C", "text": "By claiming that unschooled children receive more homework than schooled children."}, {"id": "D", "text": "By arguing that homework improves performance for students of every age."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Homework" and "Unschooling", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Homework ; https://en.wikipedia.org/wiki/Unschooling', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CT024', 'A', ARRAY['A']::TEXT[], 'Text 2''s central belief is that the more personal learning is, the more meaningful and useful it is to the child. That view treats time spent on self-chosen activity as valuable learning rather than as time lost to assignments.', '{"C": "Text 2 describes a curriculum-free practice and does not claim unschooled children receive more homework.", "B": "Text 2 explicitly encourages exploration of activities initiated by children, which is learning outside formal lessons.", "D": "Text 1 says homework generally does not improve performance among young children, and Text 2 does not assess homework''s effects at all."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CI001', 'HDSAT-RW-M17-CI001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Nuclear power is the use of nuclear reactions to produce electricity. Nuclear power can be obtained from nuclear fission, nuclear decay and nuclear fusion reactions. Presently, the vast majority of electricity from nuclear power is produced by nuclear fission of uranium and plutonium in nuclear power plants. Nuclear decay processes are used in niche applications such as radioisotope thermoelectric generators in some space probes such as Voyager 2. Reactors producing controlled fusion power have been operated since 1958 but have yet to generate net power and are not expected to be commercially available in the near future.
The first nuclear power plant was built in the 1950s. The global installed nuclear capacity grew to 100 GW in the late 1970s, and then expanded during the 1980s, reaching 300 GW by 1990. The 1979 Three Mile Island accident in the United States and the 1986 Chernobyl disaster in the Soviet Union resulted in increased regulation and public opposition to nuclear power plants.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Nuclear decay is the primary method that nuclear power plants use to generate electricity."}, {"id": "B", "text": "Fusion reactors have supplied commercial electricity since the late 1950s."}, {"id": "C", "text": "Nuclear power is generated mainly through fission today, while fusion remains an experimental technology."}, {"id": "D", "text": "Nuclear power plants rely on fusion because fission produces too little energy."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Nuclear power", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Nuclear_power', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CI001', 'C', ARRAY['C']::TEXT[], 'The passage defines nuclear power, states that fission of uranium and plutonium supplies the vast majority of nuclear electricity, and contrasts that with fusion, which has been operated since 1958 but has not yet generated net power.', '{"A": "The text says the vast majority of nuclear electricity comes from fission, while decay serves only niche applications.", "B": "The text says fusion reactors have yet to generate net power and are not expected to be commercially available soon.", "D": "The text identifies fission as the dominant source, and it never suggests that fission produces too little energy."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-INF001', 'HDSAT-RW-M17-INF001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Nuclear power is the use of nuclear reactions to produce electricity. Nuclear power can be obtained from nuclear fission, nuclear decay and nuclear fusion reactions. Presently, the vast majority of electricity from nuclear power is produced by nuclear fission of uranium and plutonium in nuclear power plants. Nuclear decay processes are used in niche applications such as radioisotope thermoelectric generators in some space probes such as Voyager 2. Reactors producing controlled fusion power have been operated since 1958 but have yet to generate net power and are not expected to be commercially available in the near future.
The first nuclear power plant was built in the 1950s. The global installed nuclear capacity grew to 100 GW in the late 1970s, and then expanded during the 1980s, reaching 300 GW by 1990. The 1979 Three Mile Island accident in the United States and the 1986 Chernobyl disaster in the Soviet Union resulted in increased regulation and public opposition to nuclear power plants.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "cannot presently serve as a commercial source of electricity."}, {"id": "B", "text": "was abandoned after the 1950s."}, {"id": "C", "text": "has replaced fission in most nuclear power plants."}, {"id": "D", "text": "is used mainly in space probes such as Voyager 2."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Nuclear power", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Nuclear_power', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-INF001', 'A', ARRAY['A']::TEXT[], 'If fusion has not produced net power and is not expected to be commercially available soon, then it cannot currently be a commercial electricity source. The passage''s other details rule out the remaining choices.', '{"C": "The text says fission supplies the vast majority of nuclear electricity, so fusion has not replaced it.", "D": "Space probes are described as using nuclear decay, not fusion.", "B": "The text says fusion reactors have been operated since 1958, not abandoned."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
