Proponents of a geographically distributed workforce argue that it reduces costs associated with maintaining an office, grants employees greater autonomy and flexibility—which improves their motivation and job satisfaction—eliminates environmental harms from commuting, allows employers to access a more geographically diverse pool of applicants, and enables employees to live where they prefer.
Opponents of remote work argue that remote telecommunications technology has been unable to fully replicate the advantages of face-to-face interaction, that employees may be more easily distracted, and that reduced social interaction may lead to feelings of isolation.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "found that remote technology fully replicated face-to-face interaction."}, {"id": "B", "text": "abandoned remote work entirely."}, {"id": "C", "text": "continued to operate with employees working outside the office."}, {"id": "D", "text": "stopped hiring employees who lived far away."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Remote work", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Remote_work', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-INF002', 'C', ARRAY['C']::TEXT[], 'Persistence of the shift means remote arrangements continued after restrictions ended. The passage supplies no support for the other outcomes.', '{"B": "The text says the shift largely persisted, which rules out abandoning it.", "A": "The text attributes the opposite view to opponents, who say technology has not fully replicated face-to-face interaction.", "D": "Proponents argue that remote work lets employers reach a more geographically diverse pool of applicants, not a narrower one."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
