ces = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CE002', 'D', ARRAY['D']::TEXT[], 'Only the correct quotation ties remote work''s spread to internet technologies such as collaborative software and videotelephony.', '{"C": "This sentence credits the pandemic, not communications technology, with the rapid transition.", "A": "This sentence lists benefits of remote work rather than explaining its growth.", "B": "This sentence lists objections to remote work rather than explaining its growth."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CI003', 'HDSAT-RW-M17-CI003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A standardized test is a test that is administered and scored in a consistent or standard manner. Standardized tests are designed in such a way that the questions and interpretations are consistent and are administered and scored in a predetermined, standard manner.
A standardized test is administered and scored uniformly for all test takers. Any test in which the same test is given in the same manner to all test takers, and graded in the same manner for everyone, is a standardized test. Standardized tests do not need to be high-stakes tests, time-limited tests, multiple-choice tests, academic tests, or tests given to large numbers of test takers. Standardized tests can take various forms, including written, oral, or practical test.  The standardized test may evaluate many subjects, including driving, creativity, athleticism, personality, professional ethics, as well as academic skills.
The opposite of standardized testing is non-standardized testing, in which either significantly different tests are given to different test takers, or the same test is assigned under significantly different conditions or evaluated differently.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "A standardized test is defined by uniform administration and scoring rather than by a particular format or purpose."}, {"id": "B", "text": "Standardized tests are defined by the number of students who take them."}, {"id": "C", "text": "Standardized tests are any tests that are scored differently for different students."}, {"id": "D", "text": "Standardized tests are always high-stakes, timed, multiple-choice academic exams."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Standardized test", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Standardized_test', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CI003', 'A', ARRAY['A']::TEXT[], 'The passage repeatedly returns to consistent administration and scoring as the defining feature, while denying that format, stakes or scale determine whether a test is standardized.', '{"D": "The text explicitly says standardized tests need not be high-stakes, time-limited, multiple-choice or academic.", "B": "The text says standardized tests need not be given to large numbers of test takers.", "C": "The text says any test graded in the same manner for everyone is standardized, the opposite of different scoring."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-INF003', 'HDSAT-RW-M17-INF003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'A standardized test is a test that is administered and scored in a consistent or standard manner. Standardized tests are designed in such a way that the questions and interpretations are consistent and are administered and scored in a predetermined, standard manner.
A standardized test is administered and scored uniformly for all test takers. Any test in which the same test is given in the same manner to all test takers, and graded in the same manner for everyone, is a standardized test. Standardized tests do not need to be high-stakes tests, time-limited tests, multiple-choice tests, academic tests, or tests given to large numbers of test takers. Standardized tests can take various forms, including written, oral, or practical test.  The standardized test may evaluate many subjects, including driving, creativity, athleticism, personality, professional ethics, as well as academic skills.
The opposite of standardized testing is non-standardized testing, in which either significantly different tests are given to different test takers, or the same test is assigned under significantly different conditions or evaluated differently.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "would be an example of standardized administration but standardized scoring."}, {"id": "B", "text": "would not qualify as standardized."}, {"id": "C", "text": "would still be standardized if it were given at the same time."}, {"id": "D", "text": "would be standardized as long as its questions were multiple-choice."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Standardized test", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Standardized_test', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-INF003', 'B', ARRAY['B']::TEXT[], 'The passage defines the opposite of standardized testing as including the same test evaluated differently. Grading essays by different standards is exactly that case.', '{"C": "Uniform timing does not make up for scoring that differs across students.", "A": "The choice contradicts itself and ignores the differing standards.", "D": "The text says a test need not be multiple-choice to be standardized, so format cannot rescue inconsistent scoring."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-TS003', 'HDSAT-RW-M17-TS003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A standardized test is a test that is administered and scored in a consistent or standard manner. Standardized tests are designed in such a way that the questions and interpretations are consistent and are administered and scored in a predetermined, standard manner.
A standardized test is administered and scored uniformly for all test takers. Any test in which the same test is given in the same manner to all test takers, and graded in the same manner for everyone, is a standardized test. Standardized tests do not need to be high-stakes tests, time-limited tests, multiple-choice tests, academic tests, or tests given to large numbers of test takers. Standardized tests can take various forms, including written, oral, or practical test.  The standardized test may evaluate many subjects, including driving, creativity, athleticism, personality, professional ethics, as well as academic skills.
The opposite of standardized testing is non-standardized testing, in which either significantly different tests are given to different test takers, or the same test is assigned under significantly different conditions or evaluated differently.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It defines standardized testing, clarifies what such tests need not be, and contrasts them with non-standardized testing."}, {"id": "B", "text": "It traces the history of standardized testing from its origins to the present."}, {"id": "C", "text": "It argues that standardized tests should be replaced by non-standardized assessments."}, {"id": "D", "text": "It compares the results of standardized tests in several countries."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Standardized test", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Standardized_test', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-TS003', 'A', ARRAY['A']::TEXT[], 'The text defines the term, elaborates on what it does and does not require, and ends by defining its opposite.', '{"B": "The text offers no historical account of standardized testing.", "C": "The text defines and describes standardized tests without recommending their replacement.", "D": "No countries or test results are compared."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
