Since the late 20th century, technological advances in lithium batteries—which offer superior energy density and current output versus lead-acid batteries—have revived public interest as zero-emission vehicle options.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "quickly displaced internal combustion engines."}, {"id": "B", "text": "were preferred over other vehicles for their high speed."}, {"id": "C", "text": "were not widely adopted even though they were quiet and easy to operate."}, {"id": "D", "text": "were used mainly for long-distance travel."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Electric vehicle", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Electric_vehicle', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-INF004', 'C', ARRAY['C']::TEXT[], 'The passage presents limited range as the obstacle to mass adoption despite the quiet, comfortable operation that made electric power attractive.', '{"A": "The text says internal combustion engines dominated for about 100 years, so electric vehicles did not displace them.", "D": "A vehicle with limited range would not be suited to long-distance travel.", "B": "The text praises quietness and ease of operation, not speed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
