Since the late 20th century, technological advances in lithium batteries—which offer superior energy density and current output versus lead-acid batteries—have revived public interest as zero-emission vehicle options.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares the purchase prices of electric and gasoline-powered vehicles."}, {"id": "B", "text": "It traces the history of electric rail vehicles before turning to cars."}, {"id": "C", "text": "It argues that electric vehicles are unsuitable for cities."}, {"id": "D", "text": "It describes the origins and early appeal of electric vehicles, explains why they lost ground, and notes their recent revival."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Electric vehicle", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Electric_vehicle', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
