INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-INF006', 'C', ARRAY['C']::TEXT[], 'Criticism focuses on the conditions in which animals are kept. Moving animals into large natural-habitat reserves changes those conditions in the direction the criticism points.', '{"D": "The text describes zoos as facilities where animals are kept for exhibition, and expanding enclosures does not imply ending exhibition.", "A": "Conservation breeding is described as common in zoos and is not tied to enclosure size.", "B": "The text does not suggest that enclosure size removes the study of animals."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
