INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CE006', 'C', ARRAY['C']::TEXT[], 'The correct quotation explicitly contrasts enclosures of a few acres with reserves spanning thousands of acres.', '{"A": "This sentence reports attendance, not size.", "B": "This sentence identifies an early modern zoo, not variation in size.", "D": "This sentence reports criticism, not size."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M17-CI007', 'HDSAT-RW-M17-CI007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Space exploration is the physical investigation of outer space by uncrewed robotic space probes and through human spaceflight.
While the observation of objects in space, known as astronomy, predates reliable recorded history, it was the development of large and relatively efficient rockets during the mid-twentieth century that allowed physical space exploration to become a reality. Common rationales for exploring space include advancing scientific research, national prestige, uniting different countries, ensuring the future survival of humanity, and developing military and strategic advantages against other countries.
The early era of space exploration was driven by a "Space Race" in which the Soviet Union and the United States vied to demonstrate their technological superiority. Landmarks of this era include the launch of the first human-made object to orbit Earth, the Soviet Union''s Sputnik 1, on 4 October 1957, and the first Moon landing by the American Apollo 11 mission on 20 July 1969. The Soviet space program achieved many of the first milestones, including the first living being in orbit in 1957, the first human spaceflight (Yuri Gagarin aboard Vostok 1) in 1961, the first spacewalk (by Alexei Leonov) on 18 March 1965, the first automatic landing on another celestial body in 1966, and the launch of the first space station (Salyut 1) in 1971. 
In the 1970s, focus shifted from one-off flights to renewable hardware, such as the Space Shuttle program, and from competition to cooperation, the foremost example being the International Space Station (ISS), built between 1998 and 2011.
The 2000s brought advancements in the national space-exploration programs of China, the European Union, Japan, and India.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The only rationale for space exploration has been national prestige."}, {"id": "B", "text": "Space exploration has been conducted only by robots, never by humans."}, {"id": "C", "text": "Space exploration grew from a Cold War competition into cooperative programs, and its rationales extend beyond science."}, {"id": "D", "text": "Space exploration ended after the Apollo 11 Moon landing."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Space exploration", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Space_exploration', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M17-CI007', 'C', ARRAY['C']::TEXT[], 'The passage lists several rationales, recounts Space Race milestones, and describes the later shift toward cooperation exemplified by the International Space Station.', '{"B": "The text describes human spaceflight, including Gagarin, Leonov and the Apollo Moon landing.", "D": "The text describes programs after Apollo, including the Space Shuttle and the International Space Station.", "A": "The text lists scientific research, national prestige, uniting countries, survival and military advantage among the rationales."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
